/* Shared, source-led discovery. A missing qualification is never a negative qualification. */
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uniq=a=>[...new Set(a)].filter(Boolean), byId=new Map(catalog.models.map(m=>[m.id,m]));
const labels={qualified:'Qualified configuration',documented:'Documented configuration',announced:'Announced',historical:'Historical qualification','not-established':'Not established',unsupported:'Explicitly unsupported'};
const pages=['finder','generations','decode','qualify'];
let page='finder', params=new URLSearchParams(), selected=[], artSerial=0, lastFocus=null, focusReturn=null;
const norm=v=>String(v).toLowerCase().replace(/[^a-z0-9]/g,'');
const amdGPU=p=>/instinct|radeon|\bmi\d/i.test(p);
const allGPU=uniq(catalog.models.flatMap(m=>m.gpuOptions.map(g=>g.product))).sort((a,b)=>Number(amdGPU(b))-Number(amdGPU(a))||a.localeCompare(b));
const allCPU=uniq([...catalog.models.flatMap(m=>m.cpuFamilies),...Object.keys(catalog.cpuAliases||{})]).sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));
const filterKeys=['q','oem','host','cpu','gpu','family','cooling','sockets','processors','dimms','dpc','channels','memoryType','lifecycle','evidence'];
function href(p='finder',obj={}){const q=new URLSearchParams();Object.entries(obj).forEach(([k,v])=>{if(v!==''&&v!=null&&v!==false)q.set(k,String(v));});return '#'+p+(q.size?'?'+q:'');}
function navigate(p,obj={}){location.hash=href(p,obj);}
function update(changes,replace=false){const q=new URLSearchParams(params);Object.entries(changes).forEach(([k,v])=>v==null||v===''||v===false?q.delete(k):q.set(k,String(v)));const next='#'+page+(q.size?'?'+q:'');if(replace){history.replaceState(null,'',next);readRoute(false);}else location.hash=next;}
function sourceLinks(ids,full=false){return uniq(ids||[]).map(id=>{const s=catalog.sources[id];if(!s)return '';const dateNote=s.date&&![s.publishedAt,s.reviewedAt,s.revisedAt].includes(s.date)&&!/^Reviewed\b/i.test(s.date)?'Source date note: '+s.date:'';const dates=[s.publishedAt?'Published '+s.publishedAt:'',s.revision?'Revision '+s.revision:'',s.revisedAt?'Revised '+s.revisedAt:'',dateNote,s.reviewedAt?'Reviewed '+s.reviewedAt:''].filter(Boolean).join(' · ')||s.date||'Review date not recorded';return `<a class="source" href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗<small>${esc(dates)}${s.loc?' · '+esc(s.loc):''}</small>${full?`<p>${esc(s.scope||'')}</p>`:''}</a>`;}).join('');}
function badge(status,label){return `<span class="support-badge ${esc(status)}">${esc(label||labels[status]||status)}</span>`;}
function serverArt(m){const prefix='finderArt'+(++artSerial)+'_';return m.art.replace(/id="([^"]+)"/g,(_,id)=>`id="${prefix+id}"`).replace(/url\(#([^)]+)\)/g,(_,id)=>`url(#${prefix+id})`).replace(/href="#([^"]+)"/g,(_,id)=>`href="#${prefix+id}"`);}
function physicalCaption(m){return `<p class="physical-caption">${m.illustration.reviewStatus==='schematic'?'Layout schematic · ':''}${esc(m.illustration.view)}</p>`;}
function physicalDetail(m){const p=m.illustration;return `<details class="physical-reference"><summary>About this illustration</summary><p><b>${esc(p.view)}</b></p><p>${esc(p.caveat)}</p><p><a href="${esc(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(p.sourceTitle)} ↗</a><br><span class="muted">${esc(p.locator)}</span></p></details>`;}
function modelMilestone(m){const g=m.generation;return g.modelYear?`${g.modelDateKind||'Documented by'} ${g.modelYear}`:'Model date unconfirmed';}
function modelYears(m){const g=m.generation;return `${g.label} · generation ${g.year} · ${modelMilestone(m)}`;}
function textMatch(m,q){
 if(!q)return true;
 const p=m.computeMemory,aliases=m.cpuFamilies.flatMap(f=>(catalog.cpuAliases||{})[f]||[]);
 const memoryTerms=[...(p.dpc||[]).map(n=>n+'DPC'),...(p.memoryTypes||[]),...(p.installedCPUCounts||[]).map(n=>n+' processors'),...(p.dimmSlotOptions||[p.dimmSlots]).filter(Number.isFinite).map(n=>n+' DIMM slots'),p.channelsPerCpu===null?'':p.channelsPerCpu+' channels'];
 // Capability search uses positive structured facts; a note saying "no 2DPC" must not match 2DPC.
 const terms=[m.name,m.oemName,m.family,m.tag,...m.cpuFamilies,...(m.aliases||[]),...aliases,...m.gpuOptions.map(g=>g.product),...(m.drive||[]),m.generation.label,m.generation.year,m.generation.modelYear,...m.events.filter(e=>e.type!=='review').map(e=>e.year),...memoryTerms];
 const hay=norm(terms.filter(v=>v!=null).join(' '));
 return q.trim().split(/\s+/).every(t=>hay.includes(norm(t)));
}
function productRequest(q=params){
 const query=q.get('q')||'',tokens=query.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean),queryNorm=norm(query);
 const matches=allGPU.filter(product=>norm(product)===queryNorm||product.toLowerCase().split(/[^a-z0-9]+/).some(token=>/^(?:mi\d+[a-z]*|l\d+[a-z]*|h\d+[a-z]*|a\d+[a-z]*|b\d+[a-z]*)$/.test(token)&&tokens.includes(token)));
 const recognized=matches.length===1?matches[0]:null,product=q.get('gpu')||recognized;
 const productTokens=new Set((recognized||'').toLowerCase().split(/[^a-z0-9]+/));
 const text=recognized&&(!q.get('gpu')||q.get('gpu')===recognized)?query.trim().split(/\s+/).filter(t=>!productTokens.has(norm(t))).join(' '):query;
 return {product,text};
}
function selectedGPU(q=params){return productRequest(q).product;}
function coolingOptions(m){return Array.isArray(m.supportedCooling)?m.supportedCooling:['Air','Liquid'].includes(m.cooling)?[m.cooling]:[];}
function memoryProfileMatch(p,q){
 const has=(values,key)=>(values||[]).filter(v=>v!=null).map(String).includes(q.get(key));
 if(q.get('processors')&&!has(p.installedCPUCounts,'processors'))return false;
 if(q.get('dimms')&&!has(p.dimmSlotOptions||[p.dimmSlots],'dimms'))return false;
 if(q.get('channels')&&(!Number.isFinite(p.channelsPerCpu)||String(p.channelsPerCpu)!==q.get('channels')))return false;
 if(q.get('dpc')&&!has(p.dpc,'dpc'))return false;
 if(q.get('memoryType')&&!has(p.memoryTypes,'memoryType'))return false;
 if(q.get('memoryType')&&q.get('dpc')&&!has(p.memoryTypeDpc?.[q.get('memoryType')],'dpc'))return false;
 if(q.get('cooling')&&p.supportedCooling&&!has(p.supportedCooling,'cooling'))return false;
 return true;
}
function memoryLayouts(m){const p=m.computeMemory;return p.memoryConfigurations?.length?p.memoryConfigurations.map(v=>({...v,maxProcessors:p.maxProcessors,scope:p.scope,nodesPerChassis:p.nodesPerChassis,dimmSlotOptions:[v.dimmSlots]})):[{...p,id:'standard',label:'Documented layout'}];}
function memoryMatch(m,q){return memoryLayouts(m).some(p=>memoryProfileMatch(p,q));}
function gpuExclusion(m,product,q=params){
 const explicit=(m.gpuExclusions||[]).find(x=>x.scope==='all'||x.products?.includes(product)||x.vendor==='AMD'&&amdGPU(product)||x.vendor==='NVIDIA'&&/^NVIDIA\b/.test(product)||x.vendor==='Intel'&&/^Intel\b/.test(product));
 if(explicit)return explicit;
 const layouts=memoryLayouts(m).filter(p=>memoryProfileMatch(p,q));
 if(layouts.length&&layouts.every(p=>p.gpuSupport==='unsupported'))return {scope:'selected-layout',reason:uniq(layouts.map(p=>p.gpuExclusionNote||p.note)).join(' '),sourceIds:m.sourceIds.filter(id=>id.includes(':memory_'))};
 return null;
}
function gpuMatch(m,product){return m.gpuOptions.filter(g=>g.product===product);}
function relationship(m,q=params){
 const cpu=q.get('cpu'),gpu=selectedGPU(q),cooling=q.get('cooling');
 if(cpu&&!m.cpuFamilies.includes(cpu))return {status:'not-established',label:'CPU pairing not established',note:'This exact CPU family is not documented for this model in the reviewed evidence.',options:[]};
 if(gpu){
  const excluded=gpuExclusion(m,gpu,q);if(excluded)return {status:'unsupported',note:excluded.reason,options:[],exclusion:excluded};
  const options=gpuMatch(m,gpu), matches=options.filter(g=>(!cpu||!g.cpuFamilies||g.cpuFamilies.includes(cpu))&&(!cooling||!g.cooling||g.cooling.includes(cooling)));
  if(!matches.length)return {status:options.length?'not-established':(m.amdGpuStatus==='unsupported'&&amdGPU(gpu)?'unsupported':'not-established'),label:options.length?'Configuration not established':undefined,note:options.length?'This GPU has a different documented CPU or cooling requirement. Inspect the configuration notes.':(amdGPU(gpu)&&m.amdGpuNote)||'No qualification for this product was established by this guide. Absence is not proof of incompatibility.',options};
  const option=matches[0];
  if(cpu&&!option.cpuFamilies&&m.cpuFamilies.length>1)return {status:option.status==='qualified'?'documented':option.status,label:(option.status==='announced'?'Announced':option.status==='historical'?'Historical':'Both listed')+' · verify pairing',note:'The model lists both products; the evidence does not establish every CPU/GPU combination. '+option.conditions,options:matches};
  if(cooling&&!option.cooling&&coolingOptions(m).length>1)return {status:option.status==='qualified'?'documented':option.status,label:(option.status==='announced'?'Announced':option.status==='historical'?'Historical':'Cooling listed')+' · verify pairing',note:'The server has this cooling option, but the reviewed evidence does not establish this exact GPU/cooling combination. '+option.conditions,options:matches};
  return {status:option.status,label:undefined,note:option.conditions,options:matches};
 }
 const status=m.lifecycle.status==='announced'?'announced':m.lifecycle.status==='withdrawn'||m.lifecycle.status==='end-of-sale'?'historical':'documented';
 return {status,label:status==='documented'?'CPU support documented':undefined,note:m.restrictions[0]||m.note,options:m.gpuOptions.filter(g=>amdGPU(g.product))};
}
function filtered(q=params){return catalog.models.filter(m=>{
 const r=relationship(m,q);
 return (!q.get('oem')||m.oem===q.get('oem'))&&(!q.get('host')||m.cpuVendor===q.get('host'))&&(!q.get('family')||m.family===q.get('family'))&&(!q.get('cooling')||coolingOptions(m).includes(q.get('cooling'))||m.gpuOptions.some(g=>(!selectedGPU(q)||g.product===selectedGPU(q))&&g.cooling?.includes(q.get('cooling'))))&&(!q.get('sockets')||String(m.sockets)===q.get('sockets'))&&memoryMatch(m,q)&&(!q.get('lifecycle')||m.lifecycle.status===q.get('lifecycle'))&&(!q.get('evidence')||r.status===q.get('evidence'))&&textMatch(m,productRequest(q).text)&&(!(q.get('cpu')||selectedGPU(q))||q.get('gaps')==='1'||!['not-established','unsupported'].includes(r.status));
 }).sort((a,b)=>{
 const sort=q.get('sort');
 if(sort==='model-newest'||sort==='model-oldest'){const ay=a.generation.modelYear,by=b.generation.modelYear;if(!ay||!by)return (ay?0:1)-(by?0:1)||a.name.localeCompare(b.name);return (sort==='model-oldest'?ay-by:by-ay)||a.name.localeCompare(b.name);}
 return sort==='oldest'?a.generation.year-b.generation.year||a.name.localeCompare(b.name):sort==='name'?a.name.localeCompare(b.name):b.generation.year-a.generation.year||a.oemName.localeCompare(b.oemName)||a.name.localeCompare(b.name);
 });}
function optionList(values,key,empty){return `<option value="">${esc(empty)}</option>`+values.map(v=>{const [value,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(value)}" ${params.get(key)===String(value)?'selected':''}>${esc(label)}</option>`;}).join('');}
function selectField(label,key,values,empty){return `<div class="field"><label for="filter-${key}">${label}</label><select id="filter-${key}" data-filter="${key}">${optionList(values,key,empty)}</select></div>`;}
function acceleratorSummary(m,q=params){
 const gpu=selectedGPU(q),r=relationship(m,q),options=gpu?r.options:m.gpuOptions.filter(g=>amdGPU(g.product));
 if(gpu&&['not-established','unsupported'].includes(r.status))return `<div class="accelerator-summary"><span class="summary-label">Requested accelerator</span><b>${esc(gpu)}</b>${badge(r.status,r.label)}<p class="availability">${r.status==='unsupported'?'Excluded by the reviewed OEM evidence.':'No matching configuration established for this request.'}</p></div>`;
 if(!options.length)return `<div class="accelerator-summary"><span class="summary-label">AMD accelerator evidence</span>${badge(m.amdGpuStatus==='unsupported'?'unsupported':'not-established')}<p class="availability">${esc(m.amdGpuNote||'No AMD accelerator qualification recorded.')}</p></div>`;
 return `<div class="accelerator-summary"><span class="summary-label">${gpu?'Requested accelerator':'AMD accelerator evidence'}</span>${options.map(g=>`<div class="accelerator-item"><b>${esc(g.product)}</b>${badge(gpu?r.status:g.status,gpu?r.label:undefined)}<p class="availability"><strong>Availability:</strong> ${esc((g.availability||'Not established').replace(/^Availability\s+/i,''))}</p>${!gpu&&g.cpuFamilies?`<p class="option-scope">CPU scope: ${esc(g.cpuFamilies.join(' / '))}</p>`:''}</div>`).join('')}</div>`;
}
function contextHref(p,m){const q=Object.fromEntries(params);delete q.view;delete q.milestone;return href(p,{...q,model:m?.id});}
function card(m){const r=relationship(m);return `<article class="platform-card" data-platform="${esc(m.id)}"><div class="card-brand"><span class="oem-label ${m.oem}">${esc(m.oemName)}</span><span>${esc(m.form)}</span></div><div class="server-art" aria-hidden="true">${serverArt(m)}</div>${physicalCaption(m)}<div class="card-content"><button class="model-name" data-model="${esc(m.id)}">${esc(m.name)} <span aria-hidden="true">↗</span></button>${memoryMetrics(m)}<p class="model-sub">${esc(m.tag)}</p><p class="date-line">${esc(modelYears(m))}</p>${selectedGPU()?'':badge(r.status,r.label)}<dl class="card-specs"><div><dt>Host CPU</dt><dd>${esc(m.cpuFamilies.join(' / '))}</dd></div><div><dt>Cooling options</dt><dd>${esc(coolingOptions(m).join(' / ')||m.cooling)}${m.coolingNote?`<small>${esc(m.coolingNote)}</small>`:''}</dd></div></dl>${acceleratorSummary(m)}<p class="restriction">${esc(r.note)}</p></div><div class="card-actions"><label><input type="checkbox" data-compare="${esc(m.id)}" ${selected.includes(m.id)?'checked':''}> Compare</label><button class="btn quiet small" data-model="${esc(m.id)}">Evidence & limits →</button></div></article>`;}
function finder(){
 const numberValues=key=>uniq(catalog.models.flatMap(m=>Array.isArray(m.computeMemory[key])?m.computeMemory[key]:[m.computeMemory[key]]).filter(Number.isFinite)).sort((a,b)=>a-b);
 const dimmValues=uniq(catalog.models.flatMap(m=>m.computeMemory.dimmSlotOptions||[m.computeMemory.dimmSlots]).filter(Number.isFinite)).sort((a,b)=>a-b);
 return `<section class="hero"><div class="hero-copy"><div class="eyebrow">THE OEM LANDSCAPE, THROUGH AN AMD LENS</div><h1>Find the platform.<br><em>Understand the fit.</em></h1><p>Connect AMD products to the servers that support them. Explore generations, inspect the evidence, and see the configuration details that change the answer.</p><div class="fact-strip"><span><b>${catalog.models.length}</b> selected platforms</span><span><b>5</b> OEMs</span><span><b>CPU + GPU</b> separate support</span></div></div><div class="hero-side" aria-label="Follow an AMD product to its OEM platform and qualification evidence"><span class="flow-label">START WITH A PRODUCT</span><div class="flow-products"><span>AMD EPYC</span><span>AMD Instinct</span></div><div class="flow-route">↓ &nbsp; Host CPU ≠ accelerator qualification &nbsp; ↓</div><div class="oem-logos"><span>CISCO</span><span>HPE</span><span>DELL</span><span>Lenovo</span><span>SUPERMICRO</span></div><div class="flow-route">↓ &nbsp; Exact model · generation · configuration &nbsp; ↓</div><span class="flow-label">READ THE EVIDENCE BEFORE THE RECOMMENDATION</span></div></section>
 <div class="workbar"><span class="muted small">Start exploring</span><button class="pill" data-preset="9005">EPYC 9005</button><button class="pill" data-preset="MI350P">Instinct MI350P</button><button class="pill" data-preset="MI355X">Instinct MI355X</button><button class="pill" data-preset="all">All platforms</button></div>
 <section class="filter-panel" aria-label="Platform filters"><div class="filters"><div class="field"><label for="platformSearch">Search model, product, codename or memory</label><input id="platformSearch" type="search" value="${esc(params.get('q')||'')}" placeholder="e.g. Turin, MI210, 2DPC" autocomplete="off"></div>${selectField('OEM','oem',Object.entries(catalog.vendors),'All five OEMs')}${selectField('CPU family','cpu',allCPU,'Any CPU family')}${selectField('Accelerator product','gpu',allGPU,'Any accelerator')}</div>
 <details class="advanced" ${['processors','dimms','dpc','channels','memoryType','sockets'].some(k=>params.get(k))?'open':''}><summary>Processor & memory filters <span>Installed CPUs, DIMM slots, channels & DPC</span></summary><div class="filters">${selectField('Documented installed processors / node','processors',numberValues('installedCPUCounts'),'Any documented CPU count')}${selectField('DIMM slots / node (all processors)','dimms',dimmValues,'Any documented slot count')}${selectField('DIMMs per channel','dpc',numberValues('dpc').map(n=>[n,n+'DPC']),'Any documented DPC')}${selectField('Memory channels / processor','channels',numberValues('channelsPerCpu'),'Any documented channels')}${selectField('Memory type','memoryType',uniq(catalog.models.flatMap(m=>m.computeMemory.memoryTypes||[])).sort(),'Any documented memory type')}${selectField('Maximum processor sockets / node','sockets',uniq(catalog.models.map(m=>m.sockets)).sort((a,b)=>a-b),'Any maximum socket count')}</div><p class="filter-note">These filters use recorded facts. Unknown values and unrecorded configurations are excluded. Slot totals are with all processors installed; a one-CPU configuration can expose fewer slots. Memory type + DPC requires a documented combination.</p></details>
 <details class="advanced" ${['host','family','cooling','lifecycle','evidence'].some(k=>params.get(k))?'open':''}><summary>Platform & evidence filters <span>Host vendor, form, cooling & lifecycle</span></summary><div class="filters">${selectField('Host CPU vendor','host',['AMD','Intel'],'Any host vendor')}${selectField('Platform family','family',uniq(catalog.models.map(m=>m.family)).sort(),'Any family')}${selectField('Documented cooling option','cooling',['Air','Liquid'],'Any cooling')}${selectField('Evidence status','evidence',Object.entries(labels),'Any evidence status')}${selectField('Model lifecycle','lifecycle',uniq(catalog.models.map(m=>m.lifecycle.status)).map(s=>[s,s==='current'?'Current reference (stock unverified)':s]),'Any lifecycle')}</div><p class="filter-note">Liquid means a documented facility-water / direct-liquid option. Air can include internal liquid-to-air cooling. Processor, memory and GPU restrictions still depend on the exact variant.</p></details>
 <div class="filter-bottom"><label class="check"><input type="checkbox" id="includeGaps" ${params.get('gaps')==='1'?'checked':''}> Include unknown and explicitly unsupported pairings</label><div><button class="btn quiet small" data-clear>Reset filters</button><button class="btn small" data-copy>Copy this view ↗</button></div></div></section>
 ${coverageView()}<div id="resultsRegion" aria-live="polite"></div>`;
}
function coverageView(){
 const c=catalog.coverage;if(!c?.oems)return '';
 const statusLabels={covered:'Covered',partial:'Partial','not-researched':'Not researched'};
 return `<details class="coverage-panel panel"><summary>How much of the OEM landscape is covered?</summary><p>${esc(c.scope||'This is a curated research catalog. A missing profile does not establish lack of OEM support.')}</p><div class="table-scroll" tabindex="0" role="region" aria-label="OEM and EPYC family research coverage"><table class="coverage-table"><thead><tr><th scope="col">OEM / EPYC</th>${c.cpuFamilies.map(f=>`<th scope="col">${esc(f.replace('EPYC ',''))}</th>`).join('')}</tr></thead><tbody>${Object.entries(catalog.vendors).map(([oem,name])=>`<tr><th scope="row">${esc(name)}</th>${c.cpuFamilies.map(f=>{const cell=c.oems[oem]?.[f]||{status:'not-researched',count:0};return `<td><a class="coverage-cell ${esc(cell.status)}" href="${esc(href('finder',{oem,cpu:f}))}"><b>${esc(statusLabels[cell.status]||'Not researched')}</b><span>${cell.count||0} profile${cell.count===1?'':'s'}</span></a></td>`;}).join('')}</tr>`).join('')}</tbody></table></div><p class="small muted">Partial means some named models are researched; covered means the stated scope has been reviewed. Neither is a market-share measure. Not researched is a catalog gap, never an incompatibility claim.</p></details>`;
}
function renderResults(){
 const list=filtered(),unknown=list.filter(m=>relationship(m).status==='not-established').length,unsupported=list.filter(m=>relationship(m).status==='unsupported').length,gpu=selectedGPU();
 const evaluated=!!(params.get('cpu')||gpu),countCopy=evaluated?`${list.length-unknown-unsupported} recorded relationships · ${unknown} not established · ${unsupported} explicitly unsupported`:'Choose a CPU or accelerator to evaluate its relationship to each model.';
 $('#resultsRegion').innerHTML=`<div class="result-head"><div><h2>${list.length} platform${list.length===1?'':'s'} <span class="muted small">in this view</span></h2><p class="small muted">${countCopy}</p>${gpu&&!params.get('gpu')?`<p class="query-recognition">Recognized accelerator: <b>${esc(gpu)}</b> · status and availability below apply to this product.</p>`:''}</div><div class="field"><label for="sort">Sort platforms</label><select id="sort" data-filter="sort">${optionList([['model-newest','Newest recorded model milestone'],['model-oldest','Oldest recorded model milestone'],['newest','Newest OEM generation'],['oldest','Oldest OEM generation'],['name','Model name']],'sort','Default: newest generation')}</select></div></div><div class="legend"><span><i class="qualified"></i>Qualified configuration</span><span><i class="announced"></i>Documented / announced</span><span><i class="historical"></i>Historical</span><span><i class="unknown"></i>Not established</span><span><i class="unsupported"></i>Explicitly unsupported</span></div>${memoryLegend()}<div class="results">${list.map(card).join('')||'<div class="empty"><h3>No researched platforms match these filters.</h3><p>Clear a filter or inspect the coverage table above. Unknown memory values and unestablished type/DPC combinations do not pass memory filters. No result does not mean no OEM support exists.</p><button class="btn" data-clear>Reset filters</button></div>'}</div><p class="result-scope">Generation year is the first documented wave. Model dates retain their evidence type: announced, available by, or documented by. A documented-by date is an upper bound, not an exact launch date; unknown dates sort last. Server drawings are illustrative. Maximum CPU, memory, storage and GPU values may require different builds.</p>`;renderTray();
}
function intro(kicker,title,copy){return `<div class="page-intro"><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${copy}</p></div>`;}
function generations(){const id=params.get('milestone'),active=catalog.milestones.find(g=>g.vendor+':'+g.id===id)||catalog.milestones.find(g=>g.vendor==='ucs'&&g.label.includes('M8'))||catalog.milestones[0];return intro('LEARN THE TIME AXIS','A generation is a starting point.','OEM generation, individual model introduction and CPU refresh are different dates. A newer generation label also does not guarantee current availability.')+`<div class="definition-grid"><div class="panel"><span class="step-number">01</span><h3>OEM generation</h3><p>First documented wave of an umbrella such as M8, Gen12, 17G or V3.</p></div><div class="panel"><span class="step-number">02</span><h3>Model milestone</h3><p>Announcement, availability, or earliest recorded evidence for the named server. “Documented by” does not establish an exact launch date.</p></div><div class="panel"><span class="step-number">03</span><h3>Product refresh</h3><p>A later CPU or GPU qualification. It may require firmware, cooling or a new system revision.</p></div><div class="panel"><span class="step-number">04</span><h3>Lifecycle event</h3><p>Announcement, orderability, shipment and end of support are separate milestones.</p></div></div><section class="section panel"><h2>Five OEMs. Five naming systems.</h2><p class="muted">Select a generation to inspect its date, scope and source.</p>${Object.entries(catalog.vendors).map(([vendor,name])=>`<div class="timeline-row"><span class="oem-label ${vendor}">${name}</span><div class="timeline-buttons">${catalog.milestones.filter(g=>g.vendor===vendor).sort((a,b)=>a.year-b.year).map(g=>`<button class="milestone" data-milestone="${vendor+':'+g.id}" aria-pressed="${active===g}"><b>${esc(g.year)}</b><span>${esc(g.label)}</span></button>`).join('')}</div></div>`).join('')}</section>${generationStory(active)}`;}
function generationStory(g){const models=catalog.models.filter(m=>m.oem===g.vendor&&m.generation.generationId===g.id);return `<section class="timeline-story panel"><div class="eyebrow">${esc(catalog.vendors[g.vendor])} · ${esc(g.dateKind||'documented milestone')}</div><h2>${esc(g.label)} · ${g.year}</h2><p>${esc(g.summary||g.note||g.dateLabel||'Inspect the generation source for the scope of this milestone.')}</p>${g.dateLabel?`<p class="small muted">${esc(g.dateLabel)}</p>`:''}<div class="sources">${sourceLinks(g.sourceIds,true)}</div><h3>Models in this curated guide</h3><div class="workbar">${models.map(m=>`<button class="pill" data-model="${m.id}">${esc(m.name)}${m.generation.modelYear?' · '+m.generation.modelYear:''}</button>`).join('')||'<p class="muted">Historical context only; no model profiles from this wave are included.</p>'}</div></section>`;}
function decode(){const q=params.get('q')||'',matches=catalog.models.filter(m=>!q||textMatch(m,q));return intro('READ THE NAME WITHOUT GUESSING','Decode the exact model.','Similar letters can mean different things across OEMs. Look up a documented model rather than assuming that a suffix always means AMD, a socket count or a CPU generation.')+`<div class="panel decode-search"><div class="field"><label for="decodeSearch">Find a model or family</label><input id="decodeSearch" type="search" value="${esc(q)}" placeholder="C245, DL385, R7725, SR665, AS-5126…"></div><p id="decodeCount" class="small muted" aria-live="polite">${matches.length} matching profiles · choose a model for its supported products, dates and evidence.</p></div><div class="decode-results">${matches.map(m=>`<article class="decode-result panel"><div class="card-brand"><span class="oem-label ${m.oem}">${m.oemName}</span><span>${esc(m.form)}</span></div><h2><button class="model-name" data-model="${m.id}">${esc(m.name)} →</button></h2><div class="decoder-pieces">${decoder(m)}</div><p class="small muted">${esc(modelYears(m))}</p><p>${esc(m.cpuFamilies.join(' / '))}</p></article>`).join('')||'<div class="empty">No exact profile found. Try a shorter model name.</div>'}</div>`;}
function decoder(m){return m.decoder.map(d=>`<div class="decoder-piece"><b>${esc(d.part)}</b><span>${esc(d.meaning)}</span></div>`).join('');}
const definitions=[['qualified','OEM documentation explicitly lists a qualified hardware configuration. Population, power, CPU and firmware conditions still apply.'],['documented','A product or configuration is listed. This may not establish the exact combined CPU/GPU build or its full software stack.'],['announced','A vendor has announced the platform or option. Shipping and final qualification can be later.'],['historical','Evidence establishes past qualification. A withdrawn option or affected end-of-sale part may still exist in installed systems.'],['not-established','This guide has not established this pairing. Do not turn an evidence gap into an incompatibility claim.'],['unsupported','Use only when authoritative evidence explicitly excludes the exact pairing. No profile is classified this way merely because an option is absent.']];
function memoryPopulation(m,selection={}){
 const layouts=memoryLayouts(m),matches=layouts.filter(p=>memoryProfileMatch(p,params));
 const p=layouts.find(p=>p.id===selection.layout)||matches[0]||layouts[0];
 const counts=p.installedCPUCounts||[],memoryType=params.get('memoryType'),dpcs=memoryType?(p.memoryTypeDpc?.[memoryType]||[]):p.dpc||[];
 const selectedCpu=Number(selection.cpu||params.get('processors')),selectedDpc=Number(selection.dpc||params.get('dpc'));
 const cpu=counts.includes(selectedCpu)?selectedCpu:counts.includes(p.maxProcessors)?p.maxProcessors:counts[0];
 const dpc=dpcs.includes(selectedDpc)?selectedDpc:dpcs[0];
 const ready=Number.isFinite(cpu)&&Number.isFinite(p.dimmSlots)&&Number.isFinite(p.channelsPerCpu)&&!!dpc;
 const requestNotes=[!memoryProfileMatch(p,params)?'The active filters do not describe this recorded layout.':'',params.get('processors')&&!counts.includes(Number(params.get('processors')))?'The requested '+params.get('processors')+'-processor configuration is not recorded for this model.':'',params.get('dpc')&&!dpcs.includes(Number(params.get('dpc')))?'The requested '+params.get('dpc')+'DPC population is not established'+(memoryType?' for '+memoryType:'')+'.':''].filter(Boolean);
 return `<section class="panel population-panel" data-population-model="${esc(m.id)}"><h3>Understand the memory layout</h3>${layouts.length>1?`<div class="field"><label for="populationLayout">Documented system layout</label><select id="populationLayout" data-population="layout">${layouts.map(v=>`<option value="${esc(v.id)}" ${v.id===p.id?'selected':''}>${esc(v.label)}</option>`).join('')}</select></div>`:''}${memoryType?`<p class="small"><b>Selected memory type:</b> ${esc(memoryType)}</p>`:''}<p>1DPC places one DIMM on each populated memory channel; 2DPC places two. Each processor owns its memory channels.</p>${requestNotes.length?`<p class="population-caption">${esc(requestNotes.join(' '))} ${ready?'The diagram shows a recorded alternative.':''}</p>`:''}${ready?`<div class="population-controls"><div class="field"><label for="populationCPU">Documented processor count</label><select id="populationCPU" data-population="cpu">${counts.map(n=>`<option value="${n}" ${n===cpu?'selected':''}>${n} processor${n===1?'':'s'}</option>`).join('')}</select></div><div class="field"><label for="populationDPC">Illustrate channel population</label><select id="populationDPC" data-population="dpc">${dpcs.map(n=>`<option value="${n}" ${n===dpc?'selected':''}>${n}DPC</option>`).join('')}</select></div></div><div class="population-diagram" aria-label="${cpu} processors with ${p.channelsPerCpu} channels each, illustrated at ${dpc} DIMMs per channel">${Array.from({length:cpu},(_,i)=>`<div class="population-cpu"><b>CPU ${i+1}</b><div class="population-channels">${Array.from({length:p.channelsPerCpu},(_,c)=>`<div class="population-channel"><span>${c+1}</span>${Array.from({length:dpc},()=>'<i aria-hidden="true"></i>').join('')}</div>`).join('')}</div><small>${p.channelsPerCpu} channels × ${dpc} DIMM${dpc===1?'':'s'} shown</small></div>`).join('')}</div><p class="population-caption">Conceptual full-channel population, per ${esc(p.scope)}. ${p.dimmSlots} physical slots are documented with ${p.maxProcessors} processor${p.maxProcessors === 1 ? "" : "s"} installed. This illustration does not establish an orderable DIMM combination, speed or capacity.</p>`:`<p class="population-caption">${!counts.length?'Supported installed processor counts are not yet recorded. ':''}${p.dimmSlots===null?'The exact slot layout is variant-dependent or unconfirmed. ':''}${!dpcs.length?(memoryType?'DPC for the selected memory type is not established. ':'DPC is not confirmed. '):''}The guide does not infer a population diagram from incomplete facts.</p>`}<p class="small muted">${esc(p.note)}</p>${p.dpcNote?`<p class="small">${esc(p.dpcNote)}</p>`:''}</section>`;
}
function supportRoutes(m){
 const resources=m.supportResources||catalog.supportResources?.[m.oem]||[];
 const items=Array.isArray(resources)?resources:Object.entries(resources).map(([kind,v])=>typeof v==='string'?{title:kind,url:v}:v);
 return `<div class="sources">${items.map(r=>`<a class="source" href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title||r.label)} ↗${r.note?`<small>${esc(r.note)}</small>`:''}</a>`).join('')}<a class="source" href="https://rocm.docs.amd.com/en/latest/compatibility/compatibility-matrix.html" target="_blank" rel="noopener">AMD ROCm compatibility matrix ↗<small>Choose the exact release, GPU, OS, kernel and framework; this link is a verification route, not a qualification claim.</small></a></div>`;
}
function modelSupport(m){
 const r=relationship(m),requested=selectedGPU();
 return `<section class="section support-context"><div class="support-context-head"><div><div class="eyebrow">${esc(m.oemName)} · SELECTED PLATFORM</div><h2>${esc(m.name)}</h2><p class="small muted">${esc(modelYears(m))}</p></div><a class="btn" href="${esc(contextHref('finder',m))}">Open platform details →</a></div><div class="detail-grid"><section class="panel"><h3>Recorded hardware evidence</h3><p><b>CPU families:</b> ${esc(m.cpuFamilies.join(' / '))}</p>${params.get('cpu')?`<p><b>Requested CPU:</b> ${esc(params.get('cpu'))}</p>`:''}${badge(r.status,r.label)}<p>${esc(r.note)}</p>${acceleratorSummary(m)}<p><b>Server lifecycle:</b> ${esc(m.lifecycle.note)}</p><div class="sources">${sourceLinks(uniq([...m.lifecycle.sourceIds,...(requested?[...r.options.flatMap(g=>g.sourceIds),...(r.exclusion?.sourceIds||[])]:m.sourceIds.slice(0,2))]))}</div></section><section class="panel"><h3>Still verify for the exact build</h3><ol class="support-checks"><li><b>Processor:</b> exact SKU, TDP, system revision and supported firmware.</li><li><b>Memory:</b> processor population, DIMM part number, type, channel population and operating speed.</li><li><b>Accelerator:</b> exact part number and quantity, risers, PSU, fans, thermal limits and any required kits.</li><li><b>Software:</b> OEM OS/firmware support, then the chosen ROCm release and application stack.</li><li><b>Availability:</b> quote date, region, shipping commitment and any lifecycle deadline for the exact option.</li></ol><p class="small muted">These are checks to complete, not facts already qualified by this dashboard.</p><h3>OEM and AMD verification routes</h3><p class="small muted">Look up ${esc(m.name)} and its exact system or board revision.</p>${supportRoutes(m)}</section></div><div class="detail-grid section">${memoryPopulation(m)}<section class="panel"><h3>Documented configuration limits</h3><ul>${m.restrictions.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${memoryEvidence(m)}<details class="disclosure"><summary>Open model evidence (${m.sourceIds.length} records)</summary><div class="sources">${sourceLinks(m.sourceIds,true)}</div></details></section></div></section>`;
}
function qualify(){
 const model=byId.get(params.get('model'));
 return intro('FROM A SHORTLIST TO A SUPPORTED BUILD','Support & availability.','Use this page to separate the hardware facts already documented from the exact-build checks still needed. Qualification, software support, orderability and end of support answer different questions.')+`<section class="panel support-picker"><div class="field"><label for="supportModel">Apply this guide to a platform</label><select id="supportModel"><option value="">Choose a researched platform</option>${Object.entries(catalog.vendors).map(([oem,name])=>`<optgroup label="${esc(name)}">${catalog.models.filter(m=>m.oem===oem).sort((a,b)=>a.name.localeCompare(b.name)).map(m=>`<option value="${esc(m.id)}" ${model?.id===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</optgroup>`).join('')}</select></div><p class="small muted">Select a model, or use “Support & availability” in its detail view. The CPU and accelerator request travels with the link.</p></section>${model?modelSupport(model):`<div class="definition-grid">${[['01','Identify the build','Exact OEM model, SKU, system revision, CPU family and accelerator part number.'],['02','Check the hardware','Population, risers, fans, power cap, PSU, backplane, memory and cooling.'],['03','Check the software','OEM firmware and OS support, then exact ROCm release, GPU, OS, kernel and framework.'],['04','Confirm deployment','Validated design, network, rack power, liquid loop, region and orderability.']].map(([n,h,p])=>`<div class="panel"><span class="step-number">${n}</span><h3>${h}</h3><p>${p}</p></div>`).join('')}</div>`}
 <details class="section panel support-definitions" ${model?'':'open'}><summary>What do the evidence labels mean?</summary><div class="definition-grid">${definitions.map(([status,description])=>`<div class="status-definition">${badge(status)}<p>${description}</p></div>`).join('')}</div><p>Evidence status describes the recorded relationship. Availability describes an option’s commercial timeline. A qualified configuration may be announced, approaching last order, or historical; a current server page does not establish stock.</p></details>
 <section class="section panel"><h2>Evidence library</h2><p class="muted">Primary OEM sources, with the claim and section each record supports. Publication, document revision and review dates stay separate when recorded.</p><div class="filters"><div class="field"><label for="sourceSearch">Search evidence</label><input id="sourceSearch" type="search" placeholder="e.g. MI350P, lifecycle, memory"></div><div class="field"><label for="sourceVendor">OEM</label><select id="sourceVendor"><option value="">All OEMs</option>${Object.entries(catalog.vendors).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div></div><p id="sourceCount" class="small muted"></p><div id="sourceResults" class="sources"></div></section>`;
}
function renderSources(){const q=norm($('#sourceSearch').value),v=$('#sourceVendor').value;const ids=Object.keys(catalog.sources).filter(id=>{const s=catalog.sources[id];return (!v||s.vendor===v)&&(!q||norm(s.title+' '+s.scope+' '+s.loc).includes(q));});$('#sourceCount').textContent=ids.length+' evidence records';$('#sourceResults').innerHTML=sourceLinks(ids,true);}
function detail(m){const r=relationship(m);return `<div class="dialog-head"><div><div class="eyebrow">${m.oemName} · ${esc(m.form)}</div><h2 id="dialogTitle">${esc(m.name)}</h2></div><button class="close" data-close aria-label="Close platform details">×</button></div><div class="dialog-content">${memoryMetrics(m)}<div class="dialog-intro"><div><p>${esc(m.job)}</p><p class="date-line">${esc(modelYears(m))}</p>${badge(r.status,r.label)}<p class="small muted">${esc(r.note)}</p></div><div class="server-art" aria-hidden="true">${serverArt(m)}</div></div>${memoryEvidence(m)}${physicalDetail(m)}<div class="modal-toolbar"><a class="btn" href="${esc(m.guide)}">Open OEM learning guide →</a><a class="btn" href="${esc(contextHref('qualify',m))}">Support & availability →</a><button class="btn" data-add="${m.id}">${selected.includes(m.id)?'Remove from comparison':'Add to comparison'}</button><button class="btn quiet" data-copy>Copy platform link ↗</button></div><div class="detail-grid"><section class="panel"><h3>Platform fundamentals</h3><dl class="card-specs">${[['CPU families',m.cpuFamilies.join(' / ')],['Host CPU',m.cpu],['Memory',m.memory],['Storage',m.storage],['Cooling',m.cooling],['Management',m.management]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p class="small muted">Maximum specifications are separate ceilings; they do not describe one guaranteed configuration.</p></section><section class="panel"><h3>Lifecycle & availability</h3><p><b>${esc(m.lifecycle.status==='current'?'Current reference':m.lifecycle.status)}</b>${m.lifecycle.date?' · '+esc(m.lifecycle.date):''}</p><p>${esc(m.lifecycle.note)}</p><div class="sources">${sourceLinks(m.lifecycle.sourceIds)}</div><p class="small muted">Review date: ${esc(m.verified)}. Lifecycle can be scoped to particular variants or option part numbers.</p></section></div><section class="section"><h3>Accelerator evidence</h3><p class="muted small">Alternative configurations. A qualified GPU is not permission to mix products or assume every CPU combination.</p>${m.gpuOptions.length?m.gpuOptions.map(g=>`<article class="gpu-option"><div class="card-brand"><h3>${esc(g.product)}</h3>${badge(g.status)}</div><p><b>Availability:</b> ${esc(g.availability)}</p>${g.cpuFamilies?`<p><b>Qualified CPU scope:</b> ${esc(g.cpuFamilies.join(' / '))}</p>`:''}<p>${esc(g.conditions)}</p><div class="sources">${sourceLinks(g.sourceIds)}</div><p class="small muted">Checked ${esc(g.verified||m.verified)}</p></article>`).join(''):`<div class="panel">${badge(m.amdGpuStatus==='unsupported'?'unsupported':'not-established')}<p>${esc(m.amdGpuNote||'No AMD GPU qualification established in the reviewed evidence.')}</p></div>`}</section><div class="detail-grid section"><section class="panel"><h3>Configuration limits to carry forward</h3><ul>${m.restrictions.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p>${esc(m.note)}</p></section><section class="panel"><h3>Read the model name</h3><div class="decoder-pieces">${decoder(m)}</div></section></div><section class="section panel"><h3>Generation, introduction & refresh</h3><div class="event-list">${m.events.map(e=>`<div class="event"><b>${e.year}</b><div><strong>${esc(e.type)}</strong><p>${esc(e.label)}</p><div class="sources">${sourceLinks(e.sourceIds)}</div></div></div>`).join('')}</div></section><details class="disclosure section"><summary>All primary profile evidence (${m.sourceIds.length} records)</summary><div class="sources">${sourceLinks(m.sourceIds,true)}</div></details></div>`;}
function compare(){
 const list=selected.map(id=>byId.get(id)),row=(name,fn)=>`<tr><th scope="row">${name}</th>${list.map(m=>`<td>${fn(m)}</td>`).join('')}</tr>`,gpu=selectedGPU(),activeIds=new Set(filtered().map(m=>m.id));
 const request=[catalog.vendors[params.get('oem')],params.get('q')&&!gpu?'Search: '+params.get('q'):'',params.get('cpu'),gpu,params.get('host')?params.get('host')+' host':'',params.get('family'),params.get('cooling')?params.get('cooling')+' cooling':'',params.get('processors')?params.get('processors')+' installed processor(s)':'',params.get('sockets')?params.get('sockets')+' max sockets':'',params.get('dimms')?params.get('dimms')+' DIMM slots':'',params.get('channels')?params.get('channels')+' channels / processor':'',params.get('dpc')?params.get('dpc')+'DPC':'',params.get('memoryType'),params.get('lifecycle')?'Model lifecycle: '+params.get('lifecycle'):'',params.get('evidence')?labels[params.get('evidence')]:''].filter(Boolean).join(' · ');
 return `<div class="dialog-head"><div><div class="eyebrow">CROSS-OEM SHORTLIST</div><h2 id="dialogTitle">Compare ${list.length} platforms</h2></div><button class="close" data-close aria-label="Close comparison">×</button></div><div class="dialog-content"><p class="muted">Compare evidence and constraints before capacity maxima. These are alternative configurations, not a validated combined bill of materials.</p>${request?`<p class="comparison-request"><b>Your request:</b> ${esc(request)}</p>`:''}<div class="modal-toolbar"><button class="btn" data-copy>Copy comparison link ↗</button></div><p class="small muted">On a narrow screen, scroll the table horizontally to see every platform.</p><div class="table-scroll" tabindex="0" role="region" aria-label="Platform comparison, scroll horizontally"><table><thead><tr><th scope="col">Platform</th>${list.map(m=>`<th scope="col">${m.oemName}<br><button class="model-name" data-model="${m.id}">${esc(m.name)}</button></th>`).join('')}</tr></thead><tbody>${memoryCompareRows(list)}${row('Matches active filters',m=>activeIds.has(m.id)?'<span class="filter-match">Matches the current filter facts</span>':'<span class="filter-mismatch">Does not match current filters</span><p>Retained in your comparison; check the changed criteria.</p>')}${row('CPU / accelerator evidence',m=>{const r=relationship(m);return badge(r.status,r.label)+'<p>'+esc(r.note)+'</p>';})}${row(gpu?'Requested accelerator & availability':'AMD accelerator evidence & availability',m=>acceleratorSummary(m))}${row('Generation & model',m=>esc(modelYears(m)))}${row('Host CPU',m=>esc(m.cpuFamilies.join(' / '))+'<p>'+esc(m.cpu)+'</p>')}${row('Form & cooling',m=>esc(m.form)+'<p>'+esc(coolingOptions(m).join(' / ')||m.cooling)+'</p>')}${row('Memory',m=>esc(m.memory))}${row('Storage',m=>esc(m.storage))}${row('Configuration limits',m=>'<ul>'+m.restrictions.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>')}${row('Server lifecycle',m=>esc(m.lifecycle.note))}${row('Continue qualification',m=>`<a class="btn" href="${esc(contextHref('qualify',m))}">Support & availability →</a>`)}${row('Verify with OEM',m=>sourceLinks(uniq([...(gpu?relationship(m).options.flatMap(g=>g.sourceIds):[]),...m.sourceIds.slice(0,2)])))}</tbody></table></div></div>`;
}
function showDialog(html){if(!$('#detailDialog').open)lastFocus=document.activeElement;$('#dialogBody').innerHTML=html;if(!$('#detailDialog').open)$('#detailDialog').showModal();$('#detailDialog .close').focus();}
function renderTray(){const el=$('#compareTray');el.hidden=!selected.length;el.innerHTML=`<div><b>${selected.length} / 4 platforms</b><p>${selected.map(id=>esc(byId.get(id).name)).join(' · ')}</p></div><div class="buttons"><button class="btn quiet" data-clear-compare>Clear</button><button class="btn primary" data-show-compare ${selected.length<2?'disabled':''}>Compare platforms →</button></div>`;$$('[data-compare]').forEach(input=>input.checked=selected.includes(input.dataset.compare));}
function toggleCompare(id){if(selected.includes(id))selected=selected.filter(x=>x!==id);else if(selected.length<4)selected.push(id);else{notice('Choose up to four platforms. Remove one to add another.');renderTray();return;}update({compare:selected.join(',')||null},true);}
function notice(message){$('#notice').textContent=message;$('#notice').hidden=false;setTimeout(()=>$('#notice').hidden=true,4000);}
async function copyLink(){try{await navigator.clipboard.writeText(location.href);notice('Link copied. Filters, platform and comparison travel with it.');}catch{const text=prompt('Copy this shareable view URL:',location.href);if(text!==null)notice('Use this URL to reopen the same view.');}}
function readRoute(full=true){const [raw,query='']=location.hash.slice(1).split('?');page=pages.includes(raw)?raw:'finder';params=new URLSearchParams(query);if(raw==='practice')history.replaceState(null,'',href('finder',Object.fromEntries(params)));selected=uniq((params.get('compare')||'').split(',')).filter(id=>byId.has(id)).slice(0,4);if(full){document.title=(page==='finder'?'AMD Platform Finder':({generations:'Generation explorer',decode:'Model decoder',qualify:'Support & availability'}[page]))+' · ChipIndex';$$('[data-nav]').forEach(a=>a.setAttribute('aria-current',a.dataset.nav===page?'page':'false'));$('#main').innerHTML=({finder,generations,decode,qualify}[page])();if(page==='qualify')renderSources();}if(page==='finder'){renderResults();$$('[data-preset]').forEach(b=>{const preset=b.dataset.preset;const active=preset==='all'?!filterKeys.some(k=>params.get(k)):preset==='9005'?params.get('cpu')==='EPYC 9005':(params.get('gpu')||'').includes(preset);b.setAttribute('aria-pressed',String(active));});}else renderTray();const m=byId.get(params.get('model'));if(m&&page!=='qualify')showDialog(detail(m));else if(params.get('view')==='compare'&&selected.length>1)showDialog(compare());else if($('#detailDialog').open)$('#detailDialog').close();}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.classList.contains('skip')){e.preventDefault();$('#main').focus();return;}if(b.dataset.model){e.preventDefault();if(!$('#detailDialog').open)focusReturn='[data-model="'+b.dataset.model+'"]';update({model:b.dataset.model,view:null});}else if(b.hasAttribute('data-close'))update({model:null,view:null});else if(b.dataset.add)toggleCompare(b.dataset.add);else if(b.hasAttribute('data-show-compare')){focusReturn='[data-show-compare]';update({view:'compare',model:null});}else if(b.hasAttribute('data-clear-compare'))update({compare:null,view:null});else if(b.hasAttribute('data-clear'))navigate('finder',{compare:selected.join(',')});else if(b.hasAttribute('data-copy'))copyLink();else if(b.dataset.milestone)update({milestone:b.dataset.milestone});else if(b.dataset.preset){const p=b.dataset.preset;const gpu=allGPU.find(g=>g.includes(p));navigate('finder',p==='all'?{}:p==='9005'?{cpu:'EPYC 9005'}:{gpu});}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.filter)update({[el.dataset.filter]:el.value,...(el.dataset.filter==='evidence'&&['not-established','unsupported'].includes(el.value)?{gaps:'1'}:{})});else if(el.dataset.compare)toggleCompare(el.dataset.compare);else if(el.id==='includeGaps')update({gaps:el.checked?'1':null});else if(el.id==='sourceVendor')renderSources();else if(el.id==='supportModel')update({model:el.value||null,view:null});else if(el.dataset.population){const panel=el.closest('[data-population-model]'),m=byId.get(panel.dataset.populationModel),value={cpu:panel.querySelector('[data-population=cpu]')?.value,dpc:panel.querySelector('[data-population=dpc]')?.value,layout:panel.querySelector('[data-population=layout]')?.value},focusId=el.id;panel.outerHTML=memoryPopulation(m,value);$('#'+focusId)?.focus();}});
document.addEventListener('input',e=>{if(e.target.id==='platformSearch')update({q:e.target.value||null},true);else if(e.target.id==='decodeSearch'){const value=e.target.value,pos=e.target.selectionStart;update({q:value||null},true);const list=catalog.models.filter(m=>textMatch(m,value));$('#decodeCount').textContent=list.length+' matching profiles · choose a model for its supported products, dates and evidence.';$('.decode-results').innerHTML=list.map(m=>`<article class="decode-result panel"><div class="eyebrow">${m.oemName}</div><h2><button class="model-name" data-model="${m.id}">${esc(m.name)} →</button></h2><div class="decoder-pieces">${decoder(m)}</div><p>${esc(modelYears(m))}</p><p>${esc(m.cpuFamilies.join(' / '))}</p></article>`).join('')||'<p>No exact profile found.</p>';}else if(e.target.id==='sourceSearch')renderSources();});
$('#detailDialog').addEventListener('cancel',e=>{e.preventDefault();update({model:null,view:null});});
$('#detailDialog').addEventListener('close',()=>{const target=focusReturn?$(focusReturn):null;if(target)target.focus();else if(lastFocus?.isConnected)lastFocus.focus();else $('#main').focus();});
window.addEventListener('hashchange',()=>readRoute());
readRoute();
